import importlib
import pkgutil
import os
from functools import partial

from ta_egate_cmd_parser.generic_commands.command import GenericCommand

module_path = 'ta_egate_cmd_parser.commands'


def get(command_name):
    """

    :param command_name:
    :return:
    """
    command_name = str(command_name).lower()
    try:
        return _import_command_class(command_name)
    except ImportError:
        return partial(GenericCommand, cmd=command_name)


def _import_command_class(command_name):
    impl = getattr(importlib.import_module(_path_to_package(command_name)), _cmd_name_to_cmd_class(command_name))
    return impl


def _cmd_name_to_cmd_class(command_name):
    return "".join([str(item).title() for item in command_name.split('_')])


def _cmd_name_to_cmd_module(command_name):
    return command_name


def _path_to_package(command_name):
    path = [module_path,
            _cmd_name_to_cmd_module(command_name)]
    return ".".join(path)


def get_egate_commands_list():
    """
    Get names of currently implemented epcsim commands
    :return:
    """
    impl = importlib.import_module(module_path)
    commands_module_path = os.path.dirname(impl.__file__)
    return '\n'.join([name for _, name, _ in pkgutil.iter_modules([commands_module_path])])
